    14	public final class ReportService {
    15	    private static final DateTimeFormatter CSV_DATE_FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM-dd");
    16	    private final ReservationService reservationService;
    17	    private final RoomRepository roomRepository;
    18	
    19	    public ReportService(ReservationService reservationService, RoomRepository roomRepository) {
    20	        this.reservationService = reservationService;
    21	        this.roomRepository = roomRepository;
    22	    }
    23	
    24	    public String generateOccupancyReport(LocalDate date) {
    25	        List<Reservation> occupiedReservations = reservationService.getOccupancyForDate(date);
    26	        List<Room> allRooms = roomRepository.findAll();
    27	
    28	        StringBuilder csv = new StringBuilder();
    29	        csv.append("room,type,reservation,check_in,check_out\n");
    30	
    31	        for (Reservation reservation : occupiedReservations) {
    32	            Room room = roomRepository.findByNumber(reservation.roomNumber()).orElseThrow();
    33	            csv.append(String.format("%d,%s,%d,%s,%s\n",
    34	                reservation.roomNumber(),
    35	                room.type(),
    36	                reservation.id(),
    37	                formatCsvDate(reservation.checkIn()),
    38	                formatCsvDate(reservation.checkOut())
    39	            ));
    40	        }
    41	
    42	        csv.append(String.format("total,%d/%d\n", occupiedReservations.size(), allRooms.size()));
    43	
    44	        return csv.toString();
    45	    }
    46	
    47	    public String generateRevenueReport(YearMonth month) {
    48	        List<Reservation> reservations = reservationService.getRevenueForMonth(month);
    49	
    50	        StringBuilder csv = new StringBuilder();
    51	        csv.append("reservation,room,check_in,check_out,status,amount\n");
    52	
    53	        BigDecimal total = BigDecimal.ZERO;
    54	
    55	        for (Reservation reservation : reservations) {
    56	            BigDecimal revenue = reservation.amountPaid().subtract(
    57	                reservation.refund() != null ? reservation.refund() : BigDecimal.ZERO
    58	            );
    59	
    60	            csv.append(String.format(Locale.US, "%d,%d,%s,%s,%s,%.2f\n",
    61	                reservation.id(),
    62	                reservation.roomNumber(),
    63	                formatCsvDate(reservation.checkIn()),
    64	                formatCsvDate(reservation.checkOut()),
    65	                reservation.status(),
    66	                revenue
    67	            ));
    68	
    69	            total = total.add(revenue);
    70	        }
    71	
    72	        csv.append(String.format(Locale.US, "total,%.2f\n", total));
    73	
    74	        return csv.toString();
    75	    }
    76	
    77	    private String formatCsvDate(LocalDate date) {
    78	        return date.format(CSV_DATE_FORMATTER);
    79	    }
    80	}
