    13	public final class ReservationService {
    14	    private final ReservationRepository reservationRepository;
    15	    private final RoomRepository roomRepository;
    16	    private final List<ReservationEventListener> listeners;
    17	
    18	    public ReservationService(
    19	        ReservationRepository reservationRepository,
    20	        RoomRepository roomRepository,
    21	        List<ReservationEventListener> listeners
    22	    ) {
    23	        this.reservationRepository = reservationRepository;
    24	        this.roomRepository = roomRepository;
    25	        this.listeners = List.copyOf(listeners);
    26	    }
    27	
    28	    public Reservation createReservation(
    29	        int roomNumber,
    30	        String guestName,
    31	        String guestEmail,
    32	        String guestCpf,
    33	        LocalDate checkIn,
    34	        LocalDate checkOut,
    35	        int guests,
    36	        RatePlan ratePlan
    37	    ) {
    38	        Room room = roomRepository.findByNumber(roomNumber)
    39	            .orElseThrow(() -> new RoomNotFoundException());
    40	
    41	        if (guests < 1) {
    42	            throw new InvalidRequestException("Guests must be at least 1");
    43	        }
    44	
    45	        if (guests > room.capacity()) {
    46	            throw new CapacityExceededException();
    47	        }
    48	
    49	        if (reservationRepository.hasConflictingReservation(roomNumber, checkIn, checkOut)) {
    50	            throw new RoomUnavailableException();
    51	        }
    52	
    53	        Reservation reservation = new Reservation(
    54	            0,
    55	            roomNumber,
    56	            guestName,
    57	            guestEmail,
    58	            guestCpf,
    59	            checkIn,
    60	            checkOut,
    61	            guests,
    62	            ratePlan,
    63	            room.nightlyRate()
    64	        );
    65	
    66	        return reservationRepository.save(reservation);
    67	    }
    68	
    69	    public Reservation confirmReservation(long id) {
    70	        Reservation reservation = reservationRepository.findById(id)
    71	            .orElseThrow(() -> new ReservationNotFoundException());
    72	
    73	        Room room = roomRepository.findByNumber(reservation.roomNumber()).orElseThrow();
    74	
    75	        reservation.confirm();
    76	        reservationRepository.update(reservation);
    77	
    78	        for (ReservationEventListener listener : listeners) {
    79	            listener.onReservationConfirmed(reservation, room.type());
    80	        }
    81	
    82	        return reservation;
    83	    }
    84	
    85	    public Reservation cancelReservation(long id) {
    86	        Reservation reservation = reservationRepository.findById(id)
    87	            .orElseThrow(() -> new ReservationNotFoundException());
    88	
    89	        Room room = roomRepository.findByNumber(reservation.roomNumber()).orElseThrow();
    90	        boolean wasPreviouslyConfirmed = reservation.wasPreviouslyConfirmed();
    91	
    92	        reservation.cancel();
    93	        reservationRepository.update(reservation);
    94	
    95	        for (ReservationEventListener listener : listeners) {
    96	            listener.onReservationCancelled(reservation, room.type(), wasPreviouslyConfirmed);
    97	        }
    98	
    99	        return reservation;
   100	    }
