   129	            .flatMap(room -> reservationRepository.findByRoomAndDateAndStatuses(
   130	                room.number(),
   131	                date,
   132	                List.of(ReservationStatus.CONFIRMED, ReservationStatus.CHECKED_IN, ReservationStatus.CHECKED_OUT)
   133	            ).stream())
   134	            .sorted((r1, r2) -> Integer.compare(r1.roomNumber(), r2.roomNumber()))
   135	            .toList();
   136	    }
