     1	package com.pousadamarealta.domain;
     2	
     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	import java.time.LocalDate;
     6	import java.time.Month;
     7	import java.util.Objects;
     8	
     9	public final class Reservation {
    10	    private final long id;
    11	    private final int roomNumber;
    12	    private final String guestName;
    13	    private final String guestEmail;
    14	    private final String guestCpf;
    15	    private final LocalDate checkIn;
    16	    private final LocalDate checkOut;
    17	    private final int guests;
    18	    private final RatePlan ratePlan;
    19	    private final int nights;
    20	    private final BigDecimal subtotal;
    21	    private final BigDecimal discount;
    22	    private final BigDecimal total;
    23	    private ReservationStatus status;
    24	    private BigDecimal amountPaid;
    25	    private BigDecimal refund;
    26	
    27	    public Reservation(
    28	        long id,
    29	        int roomNumber,
    30	        String guestName,
    31	        String guestEmail,
    32	        String guestCpf,
    33	        LocalDate checkIn,
    34	        LocalDate checkOut,
    35	        int guests,
    36	        RatePlan ratePlan,
    37	        BigDecimal nightlyRate
    38	    ) {
    39	        this.id = id;
    40	        this.roomNumber = roomNumber;
    41	        this.guestName = guestName;
    42	        this.guestEmail = guestEmail;
    43	        this.guestCpf = guestCpf;
    44	        this.checkIn = checkIn;
    45	        this.checkOut = checkOut;
    46	        this.guests = guests;
    47	        this.ratePlan = ratePlan;
    48	        this.nights = (int) checkIn.datesUntil(checkOut).count();
    49	        this.subtotal = calculateSubtotal(checkIn, checkOut, nightlyRate);
    50	        this.discount = calculateDiscount(this.subtotal, ratePlan);
    51	        this.total = this.subtotal.subtract(this.discount);
    52	        this.status = ReservationStatus.PENDING;
    53	        this.amountPaid = BigDecimal.ZERO;
    54	        this.refund = null;
    55	    }
    56	
    57	    public Reservation(
    58	        long id,
    59	        int roomNumber,
    60	        String guestName,
    61	        String guestEmail,
    62	        String guestCpf,
    63	        LocalDate checkIn,
    64	        LocalDate checkOut,
    65	        int guests,
    66	        RatePlan ratePlan,
    67	        int nights,
    68	        BigDecimal subtotal,
    69	        BigDecimal discount,
    70	        BigDecimal total,
    71	        ReservationStatus status,
    72	        BigDecimal amountPaid,
    73	        BigDecimal refund
    74	    ) {
    75	        this.id = id;
    76	        this.roomNumber = roomNumber;
    77	        this.guestName = guestName;
    78	        this.guestEmail = guestEmail;
    79	        this.guestCpf = guestCpf;
    80	        this.checkIn = checkIn;
    81	        this.checkOut = checkOut;
    82	        this.guests = guests;
    83	        this.ratePlan = ratePlan;
    84	        this.nights = nights;
    85	        this.subtotal = subtotal;
    86	        this.discount = discount;
    87	        this.total = total;
    88	        this.status = status;
    89	        this.amountPaid = amountPaid;
    90	        this.refund = refund;
    91	    }
    92	
    93	    private static BigDecimal calculateSubtotal(LocalDate checkIn, LocalDate checkOut, BigDecimal nightlyRate) {
    94	        BigDecimal sum = BigDecimal.ZERO;
    95	        LocalDate current = checkIn;
    96	        while (current.isBefore(checkOut)) {
    97	            BigDecimal rate = isHighSeason(current)
    98	                ? nightlyRate.multiply(new BigDecimal("1.20")).setScale(2, RoundingMode.HALF_EVEN)
    99	                : nightlyRate;
   100	            sum = sum.add(rate);
   101	            current = current.plusDays(1);
   102	        }
   103	        return sum.setScale(2, RoundingMode.HALF_EVEN);
   104	    }
   105	
   106	    private static boolean isHighSeason(LocalDate date) {
   107	        Month month = date.getMonth();
   108	        int day = date.getDayOfMonth();
   109	        return (month == Month.DECEMBER && day >= 15) ||
   110	               month == Month.JANUARY ||
   111	               month == Month.FEBRUARY ||
   112	               month == Month.JULY;
   113	    }
   114	
   115	    private static BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
   116	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
   117	            return subtotal.multiply(new BigDecimal("0.15")).setScale(2, RoundingMode.HALF_EVEN);
   118	        }
   119	        return BigDecimal.ZERO;
   120	    }
