    93	    private static BigDecimal calculateSubtotal(LocalDate checkIn, LocalDate checkOut, BigDecimal nightlyRate) {
    94	        BigDecimal sum = BigDecimal.ZERO;
    95	        LocalDate current = checkIn;
    96	        while (current.isBefore(checkOut)) {
    97	            BigDecimal rate = isHighSeason(current)
    98	                ? nightlyRate.multiply(new BigDecimal("1.20")).setScale(2, RoundingMode.HALF_EVEN)
    99	                : nightlyRate;
   100	            sum = sum.add(rate);
   101	            current = current.plusDays(1);
   102	        }
   103	        return sum.setScale(2, RoundingMode.HALF_EVEN);
   104	    }
   105	
   106	    private static boolean isHighSeason(LocalDate date) {
   107	        Month month = date.getMonth();
   108	        int day = date.getDayOfMonth();
   109	        return (month == Month.DECEMBER && day >= 15) ||
   110	               month == Month.JANUARY ||
   111	               month == Month.FEBRUARY ||
   112	               month == Month.JULY;
   113	    }
   114	
   115	    private static BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
   116	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
   117	            return subtotal.multiply(new BigDecimal("0.15")).setScale(2, RoundingMode.HALF_EVEN);
   118	        }
   119	        return BigDecimal.ZERO;
   120	    }
